mapper.select:
SELECT id, target, stat_code AS statCode, influence_type AS influenceType, influence_target AS influenceTarget, weight, description, display_order AS displayOrder, is_active AS isActive, created_at AS createdAt, updated_at AS updatedAt FROM wiki_stat_influence
target = #{target}
ORDER BY display_order, id

SELECT id, code, name, pitch_type AS pitchType, description, display_order AS displayOrder,
       is_active AS isActive, created_at AS createdAt, updated_at AS updatedAt
FROM wiki_pitch WHERE id = #{id}

mapper.update:
UPDATE wiki_pitch
name = #{name}, pitch_type = #{pitchType}, description = #{description}, display_order = #{displayOrder}, updated_at = NOW()
WHERE id = #{id}

UPDATE wiki_pitch_grade
velocity_min = #{velocityMin}, velocity_max = #{velocityMax}, break_amount = #{breakAmount}, description = #{description}, updated_at = NOW()
WHERE id = #{id}

UPDATE wiki_pitch_grade
SET updated_at = NOW()
WHERE pitch_code = #{pitchCode}

UPDATE wiki_stat_influence
stat_code = #{statCode}, influence_type = #{influenceType}, influence_target = #{influenceTarget}, weight = #{weight}, description = #{description}, display_order = #{displayOrder}, updated_at = NOW()
WHERE id = #{id}
